const items = $input.all();
const output = [];
for (const it of items) {
  const j = (it && it.json) || {};
  const file_id = j.id;
  const file_name = j.name || '';
  const mimeType = j.mimeType || '';
  if (!file_id) continue;
  if (mimeType === 'application/vnd.google-apps.folder') continue;
  if (mimeType === 'application/vnd.google-apps.shortcut') continue;

  const meta_url = 'https://sheets.googleapis.com/v4/spreadsheets/' + file_id + '?fields=' + encodeURIComponent('sheets.properties');

  output.push({ json: {
    file_id,
    file_name,
    mimeType,
    meta_url,
  }});
}
return output;

const metaResponses = $input.all();
const loopItems = $('Loop Files').all();

const output = [];
for (let i = 0; i < metaResponses.length; i++) {
  const respJson = (metaResponses[i] && metaResponses[i].json) || {};
  const fileMeta = ((loopItems[i] && loopItems[i].json) || {});
  const file_id = fileMeta.file_id || '';
  const file_name = fileMeta.file_name || '';

  let sheetName = 'Sheet1';
  let lastCol = 'F';
  const sheets = respJson.sheets || [];
  if (sheets[0] && sheets[0].properties) {
    sheetName = sheets[0].properties.title || 'Sheet1';
    const colCount = (sheets[0].properties.gridProperties || {}).columnCount || 6;
    if (colCount && colCount <= 26) {
      lastCol = String.fromCharCode(64 + Math.min(Math.max(colCount, 6), 26));
    }
  }

  const errorInfo = respJson.error || null;
  const range = encodeURIComponent(sheetName + '!A1:' + lastCol);
  const values_url = 'https://sheets.googleapis.com/v4/spreadsheets/' + file_id + '/values/' + range;

  output.push({ json: {
    file_id,
    file_name,
    sheet_name: sheetName,
    last_col: lastCol,
    values_url,
    meta_error: errorInfo ? (errorInfo.message || JSON.stringify(errorInfo)) : '',
  }});
}

return output;

function timeToSeconds(s) {
  if (s === undefined || s === null) return 0;
  const parts = String(s).trim().split(':').map((x) => Number(x));
  if (parts.some((p) => !Number.isFinite(p))) return 0;
  if (parts.length === 3) return parts[0]*3600 + parts[1]*60 + parts[2];
  if (parts.length === 2) return parts[0]*60 + parts[1];
  return parts[0] || 0;
}

function detectLanguage(text) {
  const t = String(text || '').toLowerCase();
  if (/\b(bonjour|merci|monsieur|madame|s'il vous pla[iî]t|au revoir|d'accord|colis|commande|client)\b/.test(t)) return 'fr-FR';
  if (/\b(hello|thanks|sir|madam|please|good ?bye|order|delivery|customer)\b/.test(t)) return 'en-US';
  if (/\b(hola|gracias|se[nñ]or(a)?|por favor|adi[oó]s|pedido|cliente)\b/.test(t)) return 'es-ES';
  return 'fr-FR';
}

function findHeader(headers, names) {
  for (const name of names) {
    const idx = headers.indexOf(name.toLowerCase());
    if (idx >= 0) return idx;
  }
  for (const name of names) {
    const ln = name.toLowerCase();
    for (let i = 0; i < headers.length; i++) {
      if (headers[i].includes(ln)) return i;
    }
  }
  return -1;
}

function makePlaceholder(file_id, file_name, reason) {
  return {
    file_id: file_id || '',
    file_name: file_name || '',
    nom_fichier: file_name || '',
    duree_appel_secondes: 0,
    transcript_text: '',
    transcript_text_for_ai: '',
    langue: 'fr-FR',
    llm_prompt: 'Réponds uniquement avec ce JSON sans markdown: {"categorisation":"Autre","description":"Fichier non analysable: ' + (reason || 'inconnu') + '","note_agent":1,"note_satisfaction_client":1,"points_amelioration":"Fichier source illisible"}',
    _placeholder: true,
    _placeholder_reason: reason || 'unknown',
  };
}

const responses = $input.all();
const urlItems = $('Build Values URL').all();

const output = [];

for (let i = 0; i < responses.length; i++) {
  const respItem = responses[i] || {};
  const respJson = (respItem && respItem.json) || {};
  const urlMeta = ((urlItems[i] && urlItems[i].json) || {});
  const file_id = urlMeta.file_id || '';
  const file_name = urlMeta.file_name || '';

  if (respJson.error) {
    const errMsg = (respJson.error && (respJson.error.message || JSON.stringify(respJson.error))) || 'unknown';
    output.push({ json: makePlaceholder(file_id, file_name, 'sheets_api_error: ' + String(errMsg).slice(0, 150)) });
    continue;
  }

  const values = respJson.values || [];
  if (values.length < 2) {
    output.push({ json: makePlaceholder(file_id, file_name, 'too_few_rows (' + values.length + ')') });
    continue;
  }

  const headers = (values[0] || []).map((h) => String(h || '').replace(/^\uFEFF/, '').trim().toLowerCase());
  const idxSpeaker = findHeader(headers, ['speaker', 'orateur', 'locuteur', 'intervenant']);
  const idxStart = findHeader(headers, ['start_time', 'start time', 'start', 'début', 'debut', 'heure debut']);
  const idxEnd = findHeader(headers, ['end_time', 'end time', 'end', 'fin', 'heure fin']);
  const idxDuration = findHeader(headers, ['duration', 'durée', 'duree']);
  const idxText = findHeader(headers, ['text', 'texte', 'transcription', 'contenu', 'content', 'message']);

  if (idxText < 0) {
    output.push({ json: makePlaceholder(file_id, file_name, 'no_text_column [' + headers.join(',') + ']') });
    continue;
  }

  const lines = [];
  let totalFromRows = 0;
  let lastEnd = 0;
  let firstStart = -1;
  for (let r = 1; r < values.length; r++) {
    const row = values[r] || [];
    const speaker = idxSpeaker >= 0 ? String(row[idxSpeaker] || '').trim() : '';
    const text = String(row[idxText] || '').trim();
    if (!text) continue;
    lines.push((speaker ? speaker + ': ' : '') + text);
    const durStr = idxDuration >= 0 ? String(row[idxDuration] || '') : '';
    totalFromRows += parseFloat(durStr) || timeToSeconds(durStr);
    const endStr = idxEnd >= 0 ? String(row[idxEnd] || '') : '';
    const endSec = parseFloat(endStr) || timeToSeconds(endStr);
    if (endSec > lastEnd) lastEnd = endSec;
    const startStr = idxStart >= 0 ? String(row[idxStart] || '') : '';
    const startSec = parseFloat(startStr) || timeToSeconds(startStr);
    if (firstStart < 0 || startSec < firstStart) firstStart = startSec;
  }

  const transcript = lines.join('\n').replace(/\r/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  if (!transcript) {
    output.push({ json: makePlaceholder(file_id, file_name, 'empty_transcript') });
    continue;
  }

  let duree = lastEnd > 0 ? lastEnd - Math.max(firstStart, 0) : 0;
  if (duree <= 0) duree = totalFromRows;
  if (duree < 0) duree = 0;

  const langue = detectLanguage(transcript);

  const FAST_MAX_CHARS = 4500;
  let chatForAi = transcript;
  if (transcript.length > FAST_MAX_CHARS) {
    const head = transcript.slice(0, 2700);
    const tail = transcript.slice(-1500);
    chatForAi = head + '\n...\n' + tail;
  }

  const llm_prompt = [
    "Analyse cette transcription d'appel téléphonique d'un service client (catalogue de vêtements/produits).",
    "La transcription contient des labels génériques (S1, S2, Orateur 1, etc.). Tu dois IDENTIFIER qui est l'OPÉRATEUR (l'agent du service client) et qui est le CLIENT, puis RÉÉCRIRE la conversation avec ces labels.",
    "Indices : l'opérateur pose des questions structurées (numéro client, code postal, références, etc.), le client donne ses infos personnelles. Les premiers messages automatiques (IVR : 'tapez 1, tapez 2'...) sont à ignorer ou marquer 'IVR'.",
    '',
    'Retourne UNIQUEMENT un JSON valide (pas de markdown, pas de texte autour).',
    'Format EXACT :',
    '{',
    '  "categorisation": "Commande|Livraison|SAV|Catalogue|Réclamation|Autre",',
    '  "description": "résumé court en 1-2 phrases",',
    '  "note_agent": 1-10,',
    '  "note_satisfaction_client": 1-10,',
    '  "points_amelioration": "axes concrets d\'amélioration pour l\'opérateur",',
    '  "conversation_relabeled": "OPÉRATEUR: ...\\nCLIENT: ...\\nOPÉRATEUR: ..." (la conversation entière réécrite avec OPÉRATEUR/CLIENT, garde les phrases mais remplace les labels S1/S2/Orateur N. Sépare chaque tour de parole par un saut de ligne)',
    '}',
    'Contraintes : description non vide ; notes entières 1..10 ; points_amelioration non vide ; categorisation parmi les 6 valeurs ; conversation_relabeled doit contenir TOUTE la conversation reformatée.',
    '',
    'fichier: ' + file_name,
    'langue: ' + langue,
    'duree_secondes: ' + Math.round(duree),
    '',
    'conversation brute :',
    chatForAi,
  ].join('\n');

  output.push({ json: {
    file_id,
    file_name,
    nom_fichier: file_name,
    duree_appel_secondes: Math.round(duree),
    transcript_text: transcript,
    transcript_text_for_ai: chatForAi,
    langue,
    llm_prompt,
    _placeholder: false,
  }});
}

return output;

const ALLOWED_CATEGORIES = ['Commande', 'Livraison', 'SAV', 'Catalogue', 'Réclamation', 'Autre'];
const pickFirstText = (...values) => { for (const v of values) { if (typeof v === 'string' && v.trim()) return v.trim(); } return ''; };
const getRawText = (json) => pickFirstText(json.text, json.output, json.response, json.answer, json.content, json.result, (json.message && json.message.content) || '');
const parseJsonBlock = (raw) => {
  if (!raw) return null;
  let t = String(raw).trim();
  if (t.startsWith('```')) t = t.replace(/^```(?:json)?\s*/i, '').replace(/```$/i, '').trim();
  const a = t.indexOf('['), b = t.lastIndexOf(']');
  if (a !== -1 && b > a) { try { return JSON.parse(t.slice(a, b+1)); } catch (e) {} }
  const f = t.indexOf('{'), l = t.lastIndexOf('}');
  if (f !== -1 && l > f) { try { return JSON.parse(t.slice(f, l+1)); } catch (e) {} }
  return null;
};
const clampScore = (value, fallback) => {
  if (typeof value === 'number' && Number.isFinite(value)) return Math.max(1, Math.min(10, Math.round(value)));
  const m = String(value ?? '').match(/-?\d+(?:\.\d+)?/);
  if (!m) return fallback;
  const n = Number(m[0]);
  if (!Number.isFinite(n)) return fallback;
  const norm = n <= 5 ? n * 2 : n;
  return Math.max(1, Math.min(10, Math.round(norm)));
};
const inferCategory = (text) => {
  const t = String(text || '').toLowerCase();
  if (!t) return 'Autre';
  if (/livraison|colis|exped|retard|transport/.test(t)) return 'Livraison';
  if (/sav|retour|panne|defect|garantie|echange/.test(t)) return 'SAV';
  if (/reclamation|plainte|rembourse|mecontent|insatisf/.test(t)) return 'Réclamation';
  if (/catalogue|reference|produit|taille|couleur/.test(t)) return 'Catalogue';
  if (/commande|panier|paiement|code avantage|coupon|promo/.test(t)) return 'Commande';
  return 'Autre';
};
const normalizeCategory = (value, transcript) => {
  const raw = String(value || '').trim();
  if (!raw) return inferCategory(transcript);
  const lo = raw.toLowerCase();
  if (lo.startsWith('livr')) return 'Livraison';
  if (lo.startsWith('sav')) return 'SAV';
  if (lo.startsWith('cat')) return 'Catalogue';
  if (lo.startsWith('récl') || lo.startsWith('recl') || lo.includes('claim')) return 'Réclamation';
  if (lo.startsWith('com') || lo.includes('order')) return 'Commande';
  if (lo.startsWith('aut')) return 'Autre';
  if (ALLOWED_CATEGORIES.includes(raw)) return raw;
  return inferCategory(transcript);
};
const fallbackDescription = (transcript, category) => {
  const cleaned = String(transcript || '').replace(/\s+/g, ' ').trim().slice(0, 220);
  if (!cleaned) return 'Analyse automatique sans transcript exploitable.';
  return (category + ': ' + cleaned).slice(0, 240);
};
const fallbackPoints = (category) => {
  if (category === 'Commande') return "Confirmer plus vite le besoin client et valider la solution en fin d'échange.";
  if (category === 'Livraison') return 'Donner un délai clair et proposer un suivi concret.';
  if (category === 'SAV') return 'Expliquer les étapes SAV de manière structurée et vérifier la compréhension.';
  if (category === 'Réclamation') return "Montrer plus d'empathie et détailler la résolution avec délai.";
  if (category === 'Catalogue') return 'Préciser les références et reformuler les options proposées.';
  return 'Améliorer la clarté des réponses et la reformulation des actions.';
};
const responses = $input.all();
const bases = $('Build Transcript Data').all();
const now = new Date().toISOString();
const output = [];
for (let idx = 0; idx < responses.length; idx++) {
  const responseItem = (responses[idx] && responses[idx].json) || {};
  const base = ((bases[idx] && bases[idx].json) || {});
  if (base._placeholder) {
    output.push({ json: {
      nom_fichier: 'DIAG: ' + (base.file_name || ('item_' + idx)),
      duree_appel_secondes: 0,
      transcript_text: 'reason=' + (base._placeholder_reason || 'unknown') + ' | file_id=' + (base.file_id || ''),
      categorisation: 'Autre',
      description: 'Placeholder (parse failed)',
      note_agent: 0,
      note_satisfaction_client: 0,
      points_amelioration: '',
      langue: base.langue || 'fr-FR',
      currentDate: now,
    }});
    continue;
  }
  const transcript = base.transcript_text || '';
  const rawText = !responseItem.error ? getRawText(responseItem) : '';
  const parsedAny = parseJsonBlock(rawText) || {};
  const r = Array.isArray(parsedAny) ? (parsedAny[0] || {}) : parsedAny;
  const cat = normalizeCategory(pickFirstText(r.categorisation, r.categorie, r.category), transcript);
  const desc = pickFirstText(r.description, r.resume, r.summary) || fallbackDescription(transcript, cat);
  const pts = pickFirstText(r.points_amelioration, r.points_amelioration_agent, r.ameliorations, r.improvements) || fallbackPoints(cat);
  // Utilise la conversation re-labelisée par l'IA (OPÉRATEUR/CLIENT) plutôt que le brut S1
  let finalTranscript = pickFirstText(r.conversation_relabeled, r.conversation, r.transcript) || transcript;
  // Tronque pour la cellule Sheet
  if (finalTranscript.length > 4000) {
    finalTranscript = finalTranscript.slice(0, 4000) + '...[tronqué]';
  }

  output.push({ json: {
    nom_fichier: base.nom_fichier || base.file_name || '',
    duree_appel_secondes: base.duree_appel_secondes || 0,
    transcript_text: finalTranscript,
    categorisation: cat,
    description: desc,
    note_agent: clampScore(r.note_agent, 7),
    note_satisfaction_client: clampScore(r.note_satisfaction_client ?? r.note_satisfaction, 8),
    points_amelioration: pts,
    langue: base.langue || '',
    currentDate: now,
  }});
}
return output;
